from functools import cache

@cache                                    # each sub-expression is solved once
def ways(expression):
    results = []
    for i, op in enumerate(expression):
        if op in "+-*":
            for a in ways(expression[:i]):
                for b in ways(expression[i + 1:]):
                    results.append(a + b if op == "+" else a - b if op == "-" else a * b)
    return tuple(results) or (int(expression),)

def diff_ways_to_compute(expression):
    return list(ways(expression))

Map<String, List<Integer>> memo = new HashMap<>();

List<Integer> diffWaysToCompute(String expression) {
    if (memo.containsKey(expression)) return memo.get(expression);   // solved before
    List<Integer> results = new ArrayList<>();
    for (int i = 0; i < expression.length(); i++) {
        char op = expression.charAt(i);
        if (op != '+' && op != '-' && op != '*') continue;
        for (int a : diffWaysToCompute(expression.substring(0, i)))
            for (int b : diffWaysToCompute(expression.substring(i + 1)))
                results.add(op == '+' ? a + b : op == '-' ? a - b : a * b);
    }
    if (results.isEmpty()) results.add(Integer.parseInt(expression));
    memo.put(expression, results);
    return results;
}

